421	void LiaStarExtension::eagerCheckStar(Node literal, Node lambda)
422	{
423	  // Eager reduction: compute every cone of p up front and emit the exact
424	  // equivalence `literal = star`. Each literal is reduced at most once.
425	  if (std::find(
426	          d_processedStarTerms.begin(), d_processedStarTerms.end(), literal)
427	      != d_processedStarTerms.end())
428	  {
429	    return;
430	  }
431	  // Normalize p to DNF and render each disjunct as a Normaliz constraint matrix.
432	  std::vector<std::pair<std::vector<std::string>, Node>> pairs =
433	      convertQFLIAToMatrices(lambda);
434	
435	  // Build the cones and the star constraints over all of them.
436	  auto [cones, starConstraints] = getCones(literal, pairs);
437	
438	  if (TraceIsOn("liastar-ext-smt"))
439	  {
440	    // Debug only: build the per-cone membership encoding (v in S, a single
441	    // element) and emit (check-sat) queries asserting it is equivalent to the
442	    // predicate, so a separate solver run can validate the cone decomposition.
443	    // The actual lemma below uses `starConstraints`, not `lia`.
444	    std::vector<std::pair<Node, Node>> lia =
445	        getMembershipDisjuncts(lambda, cones);
446	    Trace("liastar-ext") << "lia constraint: " << std::endl;
447	    traceMembershipValidation(d_nm, lambda, lia);
448	  }
449	  Node star = d_nm->mkNode(Kind::AND, starConstraints);
450	  Trace("liastar-ext") << "starConstraints: " << std::endl
451	                       << toString(starConstraints) << std::endl;
452	  star = rewrite(star);
453	  Node lemma = literal.eqNode(star);
454	  Trace("liastar-ext") << "star lemma: " << lemma << std::endl;
455	  if (d_proofGen != nullptr)
456	  {
457	    d_proofGen->registerContainsReduce(lemma, literal, star);
458	  }
459	  d_im.addPendingLemma(
460	      lemma, InferenceId::ARITH_LIA_STAR_EXISTS, d_proofGen.get());
461	  d_processedStarTerms.push_back(literal);
462	  d_im.doPendingLemmas();
463	}
