1008	void LiaStarExtension::emitDriverLemma(Node literal, MainEnum& en)
1009	{
1010	  // Emit, once per (literal, stage), the driver lemma
1011	  //     literal => (p[v] or star or guard).
1012	  // If the literal is asserted but the model certifies it neither via p[v]
1013	  // nor via the star under-approximation, the driver forces the stage guard,
1014	  // which places the enumeration skolems in a cell not covered by any cone --
1015	  // the next round then reads that cell off the model. Once every cell is
1016	  // covered the guard branch closes by conflict and only the certified
1017	  // branches remain (with `star` then exact). The lemma is satisfiability
1018	  // preserving: in any model where v is in the star set but outside the
1019	  // discovered approximation, some cell of the predicate is still uncovered,
1020	  // and the model extends to one placing the (fresh) skolems in it.
1021	  auto it = d_lastDriver.find(literal);
1022	  if (it != d_lastDriver.end() && it->second == en.guard)
1023	  {
1024	    return;
1025	  }
1026	  Node pv = LiaStarUtils::getVectorPredicate(literal, d_nm).first;
1027	  std::vector<Node> branches{pv};
1028	  auto starIt = d_lastStarLia.find(literal);
1029	  if (starIt != d_lastStarLia.end())
1030	  {
1031	    branches.push_back(starIt->second);
1032	  }
1033	  branches.push_back(en.guard);
1034	  addEnumLemma(literal.impNode(d_nm->mkNode(Kind::OR, branches)));
1035	  d_lastDriver[literal] = en.guard;
1036	}
