519	void LiaStarExtension::lazyCheckStar(Node literal, Node lambda)
520	{
521	  // Lazy reduction: drive one refinement round for `literal`. Stop refining
522	  // once the literal has been fully reduced (its term marked processed).
523	  if (std::find(
524	          d_processedStarTerms.begin(), d_processedStarTerms.end(), literal)
525	      != d_processedStarTerms.end())
526	  {
527	    return;
528	  }
529	
530	  // The persistent incremental subsolver for this lambda. On first use it is
531	  // seeded with the (nonnegative) predicate.
532	  Subsolver& sub = getSubsolver(lambda);
533	
534	  // Refine the subsolver with the cone-disjuncts discovered since the previous
535	  // round. The disjuncts are stored in bound-variable space, so map them to
