588	LiaStarExtension::getCones(
589	    Node n, const std::vector<std::pair<std::vector<std::string>, Node>>& pairs)
590	{
591	  // Eager path: build a cone for every DNF disjunct (`pairs`) and accumulate
592	  // the star constraints over all of them. Returns (cones, starConstraints):
593	  // the cones (paired with their predicate node) are used to build the
594	  // membership encoding for the debug trace, and starConstraints is the star
595	  // encoding that becomes the reduction lemma.
596	  std::vector<std::pair<Node, Cone<Integer>>> cones;
597	  std::vector<Node> vec(n.begin() + 1, n.end());
598	  size_t dimension = vec.size();
599	  std::vector<std::pair<Vector, std::vector<Vector>>> lambdas;
600	  std::vector<Node> starConstraints;
601	
602	  for (size_t i = 0; i < pairs.size(); i++)
603	  {
604	    const std::pair<std::vector<std::string>, Node>& pair = pairs[i];
605	    Trace("liastar-ext") << "---------------------------" << std::endl;
606	    Trace("liastar-ext") << "Cone for node " << i << std::endl
607	                         << pair.second << std::endl;
608	
609	    Cone<Integer> cone = LiaStarUtils::buildCone(dimension, pair.first);
610	    if (LiaStarUtils::isEmptyCone(cone))
611	    {
612	      // an infeasible disjunct contributes nothing to the star
613	      Trace("liastar-ext") << "empty cone" << std::endl;
614	      continue;
615	    }
616	
617	    for (const auto& generator : getConeGenerators(cone, dimension))
618	    {
619	      Trace("liastar-ext") << toString(generator) << std::endl;
620	      // Build the star encoding of this generator over fresh skolems (the
621	      // constraints are asserted at the top level, not under a quantifier) and
622	      // accumulate its side constraints and its (point, rays) contribution.
623	      std::vector<Node> vars, constraints;
624	      Vector point;
625	      std::vector<Vector> rays;
626	      LiaStarUtils::getGeneratorBody(dimension,
627	                                     generator,
628	                                     cone.getHilbertBasis(),
629	                                     /*star=*/true,
630	                                     /*useSkolems=*/true,
631	                                     d_nm,
632	                                     vars,
633	                                     constraints,
634	                                     point,
635	                                     rays);
636	      starConstraints.insert(
637	          starConstraints.end(), constraints.begin(), constraints.end());
638	      lambdas.push_back({point, rays});
639	    }
640	    cones.push_back({pair.second, cone});
641	  }
642	
643	  // The star vector equals the sum of every cone's contribution.
644	  std::vector<Node> sums = buildSumConstraints(d_nm, d_zero, vec, lambdas);
645	  starConstraints.insert(starConstraints.end(), sums.begin(), sums.end());
646	
647	  return std::make_pair(cones, starConstraints);
648	}

