1937	void Solver::pop()
1938	{
1939	  Assert(d_enable_incremental);
1940	
1941	  Assert(decisionLevel() == 0);
1942	  // Notify sat proof manager that we have popped and now potentially we need to
1943	  // retrieve the proofs for the clauses inserted into optimized levels
1944	  if (needProof())
1945	  {
1946	    d_pfManager->notifyPop();
1947	  }
1948	  // Pop the trail below the user level
1949	  --assertionLevel;
1950	  Trace("minisat") << "in user pop, decreasing assertion level to "
1951	                   << assertionLevel << "\n"
1952	                   << cvc5::internal::push;
1953	  while (true) {
1954	    Trace("minisat") << "== unassigning " << trail.last() << std::endl;
1955	    Var      x  = var(trail.last());
1956	    if (user_level(x) > assertionLevel) {
1957	      assigns[x] = l_Undef;
1958	      vardata[x] = VarData(CRef_Undef, -1, -1, intro_level(x), -1);
1959	      if(phase_saving >= 1 && (polarity[x] & 0x2) == 0)
1960	        polarity[x] = sign(trail.last());
1961	      insertVarOrder(x);
1962	      trail.pop();
1963	    } else {
1964	      break;
1965	    }
1966	  }
1967	
1968	  // The head should be at the trail top
1969	  qhead = trail.size();
1970	
1971	  // Remove the clauses
1972	  removeClausesAboveLevel(clauses_persistent, assertionLevel);
1973	  removeClausesAboveLevel(clauses_removable, assertionLevel);
1974	  Trace("minisat") << cvc5::internal::pop;
1975	  // Pop the SAT context to notify everyone
1976	  d_context->pop();  // SAT context for cvc5
1977	
1978	  Trace("minisat") << "MINISAT POP assertionLevel is " << assertionLevel
1979	                   << ", trail.size is " << trail.size() << "\n";
1980	  // Pop the created variables
1981	  resizeVars(assigns_lim.last());
1982	  assigns_lim.pop();
1983	
1984	  // Pop the OK
1985	  ok = trail_ok.last();
1986	  trail_ok.pop();
1987	}
